    internal static bool IsUpper(char c) => Contains(Upper, c);
    internal static bool IsLetterOrDigit(char c) => IsLetter(c) || Contains(Digits, c);
    private static bool Contains(int[] ranges, int c)
    {
        int lo = 0, hi = ranges.Length / 2 - 1;
        while (lo <= hi) { int m = (lo + hi) / 2; if (c < ranges[m*2]) hi=m-1; else if (c > ranges[m*2+1]) lo=m+1; else return true; }
        return false;
    }
